import React, { useState } from 'react';

export default function Login({ setShowLoginModal, handleLoginSubmit }) {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');

    const onSubmit = (e) => {
        e.preventDefault();
        handleLoginSubmit(username, password);
    };

    return (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.6)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
            <div style={{ display: 'flex', width: '700px', height: '400px', background: 'white', borderRadius: '15px', overflow: 'hidden', boxShadow: '0 4px 15px rgba(0,0,0,0.2)' }}>
                
                {/* වම් පැත්ත: Banner */}
                <div style={{ width: '45%', background: '#1b5e20', color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', textAlign: 'center', padding: '20px' }}>
                    <h2 style={{ margin: 0, lineHeight: '1.5' }}>Aura Pan Saku<br/>Educational<br/>Institute</h2>
                </div>
                
                {/* දකුණු පැත්ත: Form */}
                <div style={{ width: '55%', padding: '40px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
                    <h2 style={{ marginBottom: '20px', color: '#333' }}>Welcome Back!</h2>
                    <form onSubmit={onSubmit} style={{ display: 'flex', flexDirection: 'column' }}>
                        <label style={{ marginBottom: '5px', color: '#555', fontSize: '14px' }}>User Name</label>
                        <input type="text" onChange={(e) => setUsername(e.target.value)} required style={{ padding: '10px', marginBottom: '15px', border: '1px solid #ccc', borderRadius: '5px', background: '#f9f9f9' }} />
                        
                        <label style={{ marginBottom: '5px', color: '#555', fontSize: '14px' }}>Password</label>
                        <input type="password" onChange={(e) => setPassword(e.target.value)} required style={{ padding: '10px', marginBottom: '20px', border: '1px solid #ccc', borderRadius: '5px', background: '#f9f9f9' }} />
                        
                        <button type="submit" style={{ padding: '12px', background: '#2e7d32', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', fontWeight: 'bold' }}>Login</button>
                        <button type="button" onClick={() => setShowLoginModal(false)} style={{ padding: '10px', background: 'transparent', color: '#777', border: 'none', cursor: 'pointer', marginTop: '10px' }}>Cancel</button>
                    </form>
                </div>

            </div>
        </div>
    );
}
